CREATE TEMP TABLE verified_thor_brand_fix ON COMMIT DROP AS
SELECT * FROM jsonb_to_recordset($proof$[{"model": "XRI30E", "market": "CA", "pim_id": "eb5fdba6-4ba8-4e10-ac08-14eb7d00415b", "status": "needs_review", "category": "Ranges", "brand_name": "Thor Kitchen", "website_id": "567261e0-c072-4a77-bae9-1764ee5556c2", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/x-series-30-inch-professional-freestanding-induction-range", "website_category": "ranges", "identity_decision": null, "short_description": "The THOR Kitchen XRI30E is a 30-inch professional freestanding electric induction range designed for serious home cooks, featuring a 4.8 cu ft oven with versatile cooking modes including bake, roast, broil, keep warm, proof, pizza, self-clean, and air fry, all controlled via a tilt panel touch screen for easy visibility and use. The smooth glass cooktop offers four powerful induction zones, including bridge cooking for griddles or oversized cookware, and delivers precise, efficient heating, while the oven\u2019s true convection fan ensures even results. Thoughtful details such as LuxGlide\u2122 telescopic racks, a soft-close oven door, built-in casters and leveling legs, and included accessories like a broiler pan, air fry basket, and meat probe enhance convenience and performance.", "source_extracted_at": "2026-08-02T23:47:38.007+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14858233971053, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/x-series-30-inch-professional-freestanding-induction-range", "provider_product_id": 14858233971053, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "XRI30E"}, {"model": "TRF3628FFD", "market": "CA", "pim_id": "fdadcb9e-4af6-493e-8b3e-b4a80b198e34", "status": "needs_review", "category": "Refrigerators", "brand_name": "Thor Kitchen", "website_id": "14930121-90bb-4935-8710-e12e4d8a4071", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/thor-kitchen-36-inch-professional-french-door-refrigerator-with-ice-and-water-dispenser-model-trf3628ffd", "website_category": "refrigerators", "identity_decision": null, "short_description": "THOR Kitchen offers the power and performance of a premium professional appliance at a practical price. Upgrade your kitchen with this premium 36-inch full-depth French door refrigerator, offering a spacious 28.9 cu. ft. capacity and sleek stainless steel design. Engineered for performance and convenience, it features a dual ice maker, external water dispenser, and smart storage solutions for every household need.", "source_extracted_at": "2026-08-02T23:57:17.858+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14722732589421, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/thor-kitchen-36-inch-professional-french-door-refrigerator-with-ice-and-water-dispenser-model-trf3628ffd", "provider_product_id": 14722732589421, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "TRF3628FFD"}, {"model": "TUH3048", "market": "CA", "pim_id": "da1cd11c-3f1a-43e5-bff4-1872a962370d", "status": "needs_review", "category": "Ventilation", "brand_name": "Thor Kitchen", "website_id": "3891730b-1985-416a-ac1b-711642f02922", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/30-range-rood-75cm-wide-under-cabinet-hood-30-430-stainless-steel-body", "website_category": "ventilation", "identity_decision": null, "short_description": "Thor Kitchen 30 Inch Under Mounted Range Hood with powerful 480 CFM ventilation is engineered to elevate your cooking experience with strength, style, and precision. Wrapped in a durable stainless-steel finish, it delivers a sleek, modern look while standing up to the demands of everyday use. The robust 480 CFM airflow efficiently clears smoke, steam, and stubborn odors, while three adjustable fan speeds give you complete control\u2014from gentle simmering to intense searing. Designed for flexibility, this convertible unit supports both ducted and ductless installation to seamlessly fit your space. Easy push button controls ensure simple, dependable operation, and bright, energy-saving LED lights illuminate your cooktop with crisp clarity. Complete with dishwasher-safe baffle filters for effortless grease removal and long-lasting performance, this range hood empowers you to cook boldly and bring professional performance into the heart of your home. #IgniteYourCulinaryCreativity", "source_extracted_at": "2026-08-03T00:14:32.388+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14907184120173, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/30-range-rood-75cm-wide-under-cabinet-hood-30-430-stainless-steel-body", "provider_product_id": 14907184120173, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "TUH3048"}, {"model": "XRD36E", "market": "CA", "pim_id": "d1a7f12b-9a7d-47fa-995f-9955d198d0a8", "status": "needs_review", "category": "Ranges", "brand_name": "Thor Kitchen", "website_id": "c902d3b5-5271-4fb5-a18b-3fbf35a97ad3", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/36-in-professional-dual-fuel-range", "website_category": "ranges", "identity_decision": null, "short_description": "The THOR Kitchen XRD36ELP is a 36-inch professional dual-fuel range that blends powerful cooking performance with premium, user-friendly design. It features Italian brass burners that deliver up to 22,000 BTU for rapid boiling and precise simmering, continuous cast-iron grates for stability and durability, and blue LED illuminated knobs for modern style and safety. The spacious 6.0 cu ft oven includes true convection, multiple cooking modes (such as Bake, Roast, Broil, Air Fry, Proof, and Warm), dual LUXARA telescopic racks, and a soft-close door for effortless operation. Thoughtful extras like tilt panel touch controls, built-in casters with leveling legs, automatic re-ignition, and included accessories (broiler pan, air fry basket, meat probe) make everyday cooking and cleanup easier.", "source_extracted_at": "2026-08-03T00:01:31.823+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14816752206189, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/36-in-professional-dual-fuel-range", "provider_product_id": 14816752206189, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "XRD36E"}, {"model": "XRD48E", "market": "CA", "pim_id": "f2d9ea30-1d19-4854-8399-7ccaf53154ed", "status": "needs_review", "category": "Ranges", "brand_name": "Thor Kitchen", "website_id": "68c8086d-a4b6-4a51-a8d2-59c846da12d8", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/x-series-48-inch-professional-freestanding-dual-fuel-range", "website_category": "ranges", "identity_decision": null, "short_description": "The THOR Kitchen XRD48E is a 48\u2011inch professional dual\u2011fuel range built for ambitious home chefs, featuring Italian brass burners including three powerful 22,000\u202fBTU dual\u2011flame burners, a griddle burner, and additional high\u2011output burners for versatile cooktop performance. It includes a double oven configuration (4.8\u202fcu\u202fft and 2.2\u202fcu\u202fft) with independent temperature controls and a wide range of cooking modes such as Bake, Broil, Convection Bake/Roast, Air Fry, Proof, and Self\u2011Clean, all managed from a responsive tilt panel touch control. Premium touches like luxurious telescopic racks, soft\u2011close oven doors, continuous cast\u2011iron grates, blue LED illuminated knobs, built\u2011in casters with leveling legs, and automatic re\u2011ignition enhance functionality and ease of use, while included accessories (broiler pan, air fry basket, meat probe, grill/griddle grate) expand versatility and convenience in the kitchen.", "source_extracted_at": "2026-08-03T00:08:23.433+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14852760863085, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/x-series-48-inch-professional-freestanding-dual-fuel-range", "provider_product_id": 14852760863085, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "XRD48E"}, {"model": "XRI36E", "market": "CA", "pim_id": "c517f372-69ca-4bbb-99f9-31a56e24c62c", "status": "needs_review", "category": "Ranges", "brand_name": "Thor Kitchen", "website_id": "2f1d12ab-9290-45e6-a0cf-1a7ea665bd50", "source_type": "scraper_v2", "website_brand": "MVP Sales & Marketing North America", "organization_id": "00000000-0000-0000-0000-000000000002", "source_reference": "https://www.thorkitchen.com/products/x-series-36-inch-professional-freestanding-induction-range-xri36e", "website_category": "ranges", "identity_decision": null, "short_description": "The THOR Kitchen XRI36E is a premium 36-inch professional freestanding induction range that combines powerful performance with advanced features to elevate your home cooking. It offers a spacious 6.0 cu. ft. true convection oven with versatile cooking modes including Bake, Roast, Broil, Keep Warm, Proof, Pizza, Self-Clean, and Air-Fry, all managed from an intuitive tilt panel touch screen. The induction cooktop delivers precise heat with five cooking zones\u2014including bridge elements for larger cookware\u2014while LuxGlide\u2122 telescopic racks, a soft-close oven door, and built-in casters with leveling legs add convenience and professional-grade usability. Thoughtful touches like a true convection fan, smooth frameless glass top, and included accessories such as a broiler pan, air fry basket, and meat probe ensure seamless, efficient cooking and cleanup.", "source_extracted_at": "2026-08-02T23:47:50.315+00:00", "exact_sku_verified": true, "manufacturer_product_id": 14858239738221, "manufacturer_updated_at": "2026-10-11T12:21:17-07:00", "source_page": "https://www.thorkitchen.com/products/x-series-36-inch-professional-freestanding-induction-range-xri36e", "provider_product_id": 14858239738221, "provider_updated_at": "2026-10-11T12:21:17-07:00", "exact_sku": "XRI36E"}]$proof$::jsonb) AS x(pim_id uuid,organization_id uuid,model text,brand_name text,market text,category text,website_id uuid,website_brand text,status text,website_category text,source_page text,provider_product_id bigint,provider_updated_at timestamptz,manufacturer_title text,exact_sku text);
CREATE TEMP TABLE before_thor_brand_fix ON COMMIT DROP AS
SELECT p.id,to_jsonb(p) before_values,x.pim_id,x.organization_id,x.source_page,x.provider_product_id,x.provider_updated_at,x.exact_sku
FROM verified_thor_brand_fix x JOIN public.products p ON p.id=x.website_id
JOIN tj.aiq_products t ON t.id=x.pim_id
WHERE p.brand_name='MVP Sales & Marketing North America' AND p.status='needs_review'
AND t.brand_name='Thor Kitchen' AND t.model=x.exact_sku AND tj_private.pim_web_image_appliance(t)
AND tj_private.pim_web_key(p.model_number)=tj_private.pim_web_key(t.model)
AND p.category=tj_private.pim_web_category(t.category) AND (p.market IS NULL OR p.market=t.market)
AND (SELECT count(*) FROM public.products y WHERE tj_private.pim_web_key(y.model_number)=tj_private.pim_web_key(t.model))=1;
UPDATE public.products p SET brand_name='Thor Kitchen',brand_canonical_id=public.brand_resolve('Thor Kitchen'),write_source='pim_catalog_completion'
FROM before_thor_brand_fix b WHERE p.id=b.id;
DO $check$ BEGIN
IF EXISTS(SELECT 1 FROM before_thor_brand_fix b JOIN public.products p ON p.id=b.id
WHERE (b.before_values - ARRAY['brand_name','brand_canonical_id','write_source','updated_at','normalized_brand_name']) IS DISTINCT FROM
(to_jsonb(p) - ARRAY['brand_name','brand_canonical_id','write_source','updated_at','normalized_brand_name']))
THEN RAISE EXCEPTION 'Unexpected non-brand catalog change'; END IF;
END $check$;
INSERT INTO tj_private.pim_web_completion_log(organization_id,pim_product_id,website_product_id,source_updated_at,action,before_values,after_values,detail)
SELECT b.organization_id,b.pim_id,b.id,b.provider_updated_at,'manufacturer_brand_correction',b.before_values,to_jsonb(p),
jsonb_build_object('operation','correct_exact_model_thor_distributor_brand','manufacturer_source',b.source_page,'manufacturer_product_id',b.provider_product_id,'exact_sku',b.exact_sku,'checked_on','2026-10-11','existing_status_preserved',true,'photos_specs_prices_preserved',true)
FROM before_thor_brand_fix b JOIN public.products p ON p.id=b.id;
INSERT INTO tj_private.pim_web_completion_queue(pim_product_id,organization_id)
SELECT pim_id,organization_id FROM before_thor_brand_fix
ON CONFLICT(pim_product_id) DO UPDATE SET queued_at=clock_timestamp(),processed_at=NULL
WHERE tj_private.pim_web_completion_queue.processed_at IS NOT NULL AND tj_private.pim_web_completion_queue.last_error IS NULL;
SELECT count(*) corrected_brands FROM before_thor_brand_fix;
COMMIT;
